function MoldWashBoothMaker.init() MoldWashBoothMaker.ironStock=14; MoldWashBoothMaker.bronzeStock=12; MoldWashBoothMaker.woodStock=14; MoldWashBoothMaker.leatherStock=10; MoldWashBoothMaker.silverStock=8; MoldWashBoothMaker.goldStock=6; MoldWashBoothMaker.jewelStock=4; MoldWashBoothMaker.pearlStock=4; MoldWashBoothMaker.productStock={}; MoldWashBoothMaker.buildings={}; MoldWashBoothMaker.maker=nil; MoldWashBoothMaker.activeMaking={}; MoldWashBoothMaker.totalProducts=0; MoldWashBoothMaker.dayTimer=0; print("[MoldWashBoothMaker] Royal Mold Wash Booth Maker System initialized (6 products, 4 buildings)") end
function MoldWashBoothMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; MoldWashBoothMaker.maker={name=n or ("Kabinar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kabinar najet: %s (spretnost: %d)",MoldWashBoothMaker.maker.name,s),"success") end; return true end
function MoldWashBoothMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function MoldWashBoothMaker.build(id) local ok,e=MoldWashBoothMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(MoldWashBoothMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function MoldWashBoothMaker.getQualityBonus() local b=0; for _,bd in ipairs(MoldWashBoothMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function MoldWashBoothMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and MoldWashBoothMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and MoldWashBoothMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and MoldWashBoothMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and MoldWashBoothMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and MoldWashBoothMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and MoldWashBoothMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and MoldWashBoothMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and MoldWashBoothMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #MoldWashBoothMaker.buildings==0 then return false,"Potrebna kabinska delavnica" end; if not MoldWashBoothMaker.maker then return false,"Potreben kabinar" end; return true end
function MoldWashBoothMaker.make(pt,qty) qty=qty or 1; local ok,e=MoldWashBoothMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then MoldWashBoothMaker.ironStock=MoldWashBoothMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then MoldWashBoothMaker.bronzeStock=MoldWashBoothMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then MoldWashBoothMaker.woodStock=MoldWashBoothMaker.woodStock-d.woodCost*qty end; if d.leatherCost then MoldWashBoothMaker.leatherStock=MoldWashBoothMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then MoldWashBoothMaker.silverStock=MoldWashBoothMaker.silverStock-d.silverCost*qty end; if d.goldCost then MoldWashBoothMaker.goldStock=MoldWashBoothMaker.goldStock-d.goldCost*qty end; if d.jewelCost then MoldWashBoothMaker.jewelStock=MoldWashBoothMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then MoldWashBoothMaker.pearlStock=MoldWashBoothMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if MoldWashBoothMaker.maker then t=math.max(1,t-math.floor(MoldWashBoothMaker.maker.skill/13)) end; table.insert(MoldWashBoothMaker.activeMaking,{id="moldwashbooth_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function MoldWashBoothMaker.completeMaking(m) local q=1.0+(MoldWashBoothMaker.getQualityBonus()/100); if MoldWashBoothMaker.maker then q=q+(MoldWashBoothMaker.maker.skill/140) end; q=math.min(2.5,q); MoldWashBoothMaker.productStock[m.productType]=(MoldWashBoothMaker.productStock[m.productType] or 0)+m.quantity; MoldWashBoothMaker.totalProducts=MoldWashBoothMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if MoldWashBoothMaker.maker then MoldWashBoothMaker.maker.itemsMade=MoldWashBoothMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then MoldWashBoothMaker.maker.skill=math.min(100,MoldWashBoothMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kabina izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"moldwashbooth.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function MoldWashBoothMaker.update(dt) if not _G.state then return end; MoldWashBoothMaker.dayTimer=MoldWashBoothMaker.dayTimer+dt; if MoldWashBoothMaker.dayTimer>=30 then MoldWashBoothMaker.dayTimer=0; for i=#MoldWashBoothMaker.activeMaking,1,-1 do local m=MoldWashBoothMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then MoldWashBoothMaker.completeMaking(m); table.remove(MoldWashBoothMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(MoldWashBoothMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if MoldWashBoothMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function MoldWashBoothMaker.getStats() return {ironStock=MoldWashBoothMaker.ironStock,bronzeStock=MoldWashBoothMaker.bronzeStock,woodStock=MoldWashBoothMaker.woodStock,leatherStock=MoldWashBoothMaker.leatherStock,silverStock=MoldWashBoothMaker.silverStock,goldStock=MoldWashBoothMaker.goldStock,jewelStock=MoldWashBoothMaker.jewelStock,pearlStock=MoldWashBoothMaker.pearlStock,productStock=MoldWashBoothMaker.productStock,numBuildings=#MoldWashBoothMaker.buildings,hasMaker=MoldWashBoothMaker.maker~=nil,makerName=MoldWashBoothMaker.maker and MoldWashBoothMaker.maker.name or "—",makerSkill=MoldWashBoothMaker.maker and MoldWashBoothMaker.maker.skill or 0,activeMaking=#MoldWashBoothMaker.activeMaking,totalProducts=MoldWashBoothMaker.totalProducts} end
